package io.github.isidorotrevino.planner.postgres;
import org.junit.jupiter.api.*;
import java.sql.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.isidorotrevino.planner.postgres.DeliveryStoreTest.*;
class RecoveryV1StoreTest {
 CheckpointStoreTest f;UUID receiver=id();
 @BeforeEach void setup(TestInfo info)throws Exception{f=new CheckpointStoreTest();f.setup(info);String before;try(var c=f.f.owner()){before=value(c,"SELECT to_jsonb(l)::text FROM operation_leases l");}assertEquals(5,migrations(f.f.db,"26").migrate().migrationsExecuted);try(var c=f.f.owner()){assertEquals(before,value(c,"SELECT to_jsonb(l)::text FROM operation_leases l"));f.call(c,"lab_authorize",id(),f.f.worker,f.delivery,receiver);sql(c,"UPDATE operation_leases SET expires_at=clock_timestamp()-interval '1 second'");f.call(c,"lab_admin",id(),f.delivery,"EXPIRE",null);}}
 @AfterEach void cleanup()throws Exception{if(f!=null)f.cleanup();}
 String proof(boolean terminal)throws Exception{try(var c=f.f.owner()){return value(c,"SELECT (i||jsonb_build_object('schema','d4.recovery.proof.v1','process_stopped',true,'artifact_valid',true,'receiver_closed',true,'host_observation_hash',repeat('a',64),'stdout_hash',repeat('b',64),'stderr_hash',repeat('c',64),'close_sequence',10,'receipts',r,'receiver_seal',jsonb_build_object('receiverId',?::uuid,'sequence',10,'steps',r,'identity',jsonb_build_object('operation',i->'operation','attempt',i->'attempt','worker',i->'worker','resource',i->'resource','generation',i->'generation'))))::text FROM (SELECT i,jsonb_object_agg(s->>'id',jsonb_build_object('status',CASE WHEN ? OR s->>'id'='step-1' THEN 'APPLIED' ELSE 'ABSENT' END,'generation',i->'generation','closed',true,'payloadHash',s->'effect_hash')) r FROM (SELECT d4.recovery_info(?) i) z CROSS JOIN LATERAL jsonb_array_elements(i->'recovery_manifest'->'steps') s GROUP BY i) q",receiver,terminal,f.delivery);}}
 UUID settle(boolean terminal)throws Exception{try(var c=f.f.owner()){var p=id();value(c,"SELECT d4.recovery_record(?,?,?::jsonb)::text",p,f.delivery,proof(terminal));var cid=id();f.call(c,"recovery_settle",cid,p,Long.parseLong(value(c,"SELECT row_version FROM operations")));return cid;}}
 @Test void v1PartialCreatesNativeCheckpointAndPreservesUnknownFacts()throws Exception{try(var c=f.f.owner()){sql(c,"INSERT INTO d2.effect_receipts(operation_id,generation,effect_key,status,evidence_ref) SELECT id,1,id||'/'||context_pack_sha256||'/step-2','UNKNOWN','synthetic-prior' FROM operations");}var cp=settle(false);try(var c=f.f.owner()){assertEquals("CANCELLED",value(c,"SELECT state FROM operations"));assertEquals("1",value(c,"SELECT count(*) FROM d4.checkpoints"));assertEquals("1",value(c,"SELECT count(*) FROM d2.effect_receipts WHERE status='UNKNOWN'"));f.call(c,"authorize_continuation",id(),cp,Long.parseLong(value(c,"SELECT row_version FROM operations")),"Explicit recovered v1 continuation");assertEquals("true",value(c,"SELECT d4.continuation_safe(?,1)::text",f.f.operation));assertEquals("READY",value(c,"SELECT state FROM operations"));assertEquals("0/4",value(c,"SELECT outstanding::int||'/'||consumed::int FROM d2.reservation_balances"));}}
 @Test void v1TerminalSettlesAndAcceptsWithoutAnotherAttempt()throws Exception{var sid=settle(true);try(var c=f.f.owner()){assertEquals("0/10",value(c,"SELECT outstanding::int||'/'||consumed::int FROM d2.reservation_balances"));assertEquals("VERIFYING",value(c,"SELECT state FROM operations"));assertEquals("0",value(c,"SELECT count(*) FROM execution_evidence"));f.call(c,"recovery_accept",id(),sid);assertEquals("COMPLETED",value(c,"SELECT state FROM operations"));assertEquals("1",value(c,"SELECT count(*) FROM execution_attempts"));}}
 @Test void v1AppliedCannotBecomeAbsent()throws Exception{try(var c=f.f.owner()){sql(c,"INSERT INTO d2.effect_receipts(operation_id,generation,effect_key,status,evidence_ref) SELECT id,1,id||'/'||context_pack_sha256||'/step-2','APPLIED','synthetic-prior' FROM operations");assertEquals("23514",assertThrows(SQLException.class,()->settle(false)).getSQLState());assertEquals("10/0",value(c,"SELECT outstanding::int||'/'||consumed::int FROM d2.reservation_balances"));}}
}
